package com.campus.lostfound.entity;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.time.LocalDate; import java.time.LocalDateTime;
@Entity @Table(name="items") @Inheritance(strategy=InheritanceType.SINGLE_TABLE) @DiscriminatorColumn(name="item_type")
public abstract class Item { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Size(max=100) @Column(nullable=false) private String name; @NotBlank @Column(nullable=false) private String category; @NotBlank @Column(nullable=false) private String location; @NotNull @Column(nullable=false) private LocalDate itemDate; @Column(length=1000) private String description; private String imagePath; @Enumerated(EnumType.STRING) @Column(nullable=false) private ItemStatus status=ItemStatus.PENDING; @ManyToOne(optional=false) @JoinColumn(name="reporter_id") private User reporter; private LocalDateTime createdAt=LocalDateTime.now(); protected Item(){} protected Item(String name,String category,String location,LocalDate date,String description,User reporter){this.name=name;this.category=category;this.location=location;this.itemDate=date;this.description=description;this.reporter=reporter;}
 public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public LocalDate getItemDate(){return itemDate;} public void setItemDate(LocalDate v){itemDate=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getImagePath(){return imagePath;} public void setImagePath(String v){imagePath=v;} public ItemStatus getStatus(){return status;} public void setStatus(ItemStatus v){status=v;} public User getReporter(){return reporter;} public void setReporter(User v){reporter=v;} public LocalDateTime getCreatedAt(){return createdAt;} public abstract String getType(); }
